/** UUIDv7 identifiers (ADR 0004). Time-ordered, generated by the application. */
export type Id = string & { readonly __brand: "Id" };

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export const newId = (): Id => Bun.randomUUIDv7() as Id;

export const isId = (value: string): value is Id => UUID_RE.test(value);
